import csv,collections
r=list(csv.DictReader(open('responses.csv')))
d=collections.defaultdict(list)
for x in r: d[x['number_set']].append((int(x['target']),int(x['rating'])))
for s in d:
  if s.startswith('31,3,1'):
    print(s, sorted(collections.Counter(t for t,_ in d[s]).items())[:5])
    agg=collections.defaultdict(list)
    for t,y in d[s]: agg[t].append(y)
    print({t:round(sum(v)/len(v),2) for t,v in sorted(agg.items())})
print(len(r),len(d))
"

